      try {
        domMethod = document.documentElement.getAttribute("data-lovasiri-method") || "";
      } catch (_) {}
      var rawMethod = domMethod || window.__lovasiri_native_method || "v6";
      var selectedMethod = rawMethod === "v5" ? "v5" : (rawMethod === "v7" ? "v7" : "v6");
      
      var selectedIntent = "fix_error";
      if (selectedMethod === "v5") selectedIntent = "security_scan";
      else if (selectedMethod === "v7") selectedIntent = "deploy_error"; // Method 3: Advanced Sending
      
